export const getPopularGarments = () => garmentTypes.filter(g => g.popular);

export const getGarmentsByCategory = (category: GarmentCategory) => 
  garmentTypes.filter(g => g.category === category);

export const searchGarments = (query: string, language: string = "en") => {
  const lowerQuery = query.toLowerCase();
  return garmentTypes.filter(g => 
    language === "en" 
      ? g.name.toLowerCase().includes(lowerQuery)
      : g.nameAr.includes(query)
  );
};

export async function loadGarmentsWithAIIcons(): Promise<GarmentType[]> {
  try {
    const AsyncStorage = (await import('@react-native-async-storage/async-storage')).default;
    const cached = await AsyncStorage.getItem('ai_garment_icons');
    if (!cached) {
      return garmentTypes;
    }
    
    const iconMap: Record<string, string> = JSON.parse(cached);
    
    return garmentTypes.map(garment => ({
      ...garment,
      aiIcon: iconMap[garment.id] || undefined,
    }));
  } catch (error) {
    console.error('Failed to load AI icons:', error);
    return garmentTypes;
  }
}
